import{_ as a,c as t,o as r,a3 as o}from"./chunks/framework.BT-mtt1U.js";const u=JSON.parse('{"title":"PE (Public Examination)","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Exams-Assignments.md","filePath":"wiki/Exams-Assignments.md","lastUpdated":null}'),s={name:"wiki/Exams-Assignments.md"};function n(i,e,l,c,m,d){return r(),t("div",null,e[0]||(e[0]=[o('<h2 id="examination-tma-practical-pcp-info" tabindex="-1">Examination/TMA/Practical/PCP Info <a class="header-anchor" href="#examination-tma-practical-pcp-info" aria-label="Permalink to &quot;Examination/TMA/Practical/PCP Info&quot;">​</a></h2><h1 id="pe-public-examination" tabindex="-1">PE (Public Examination) <a class="header-anchor" href="#pe-public-examination" aria-label="Permalink to &quot;PE (Public Examination)&quot;">​</a></h1><p>The Public Examinations are held <strong>twice</strong> a year in the months of April-May and October-November. Eligibility criteria for writing PE: all students admitted under <strong>stream 1 &amp; 2</strong> can pay the exam fees and appear for the exam. <a href="https://drive.google.com/file/d/1SQAL7MZbkI2XUnyTSU0Nl0RbVB82HXKF/view?usp=drivesdk" target="_blank" rel="noreferrer">How to pay exam fees?</a></p><blockquote><p>Please note that <strong>students of stream 2 don&#39;t have to pay exam fees for the first time.</strong></p></blockquote><h1 id="ode-on-demand-examination" tabindex="-1">ODE (On-Demand Examination) <a class="header-anchor" href="#ode-on-demand-examination" aria-label="Permalink to &quot;ODE (On-Demand Examination)&quot;">​</a></h1><p>What is NIOS ODE? ODE (On-Demand Examination) is a flexible examination system offered by NIOS. It allows students to choose their exam centres based on their convenience. It operates under two main student categories and is available for both Class 10 (Sec) (Stream 3) and Class 12 (Sr.Sec) (Stream 4) levels.</p><p>It runs under two main categories of students:</p><ol><li>Students who have failed or got compartment from any recognised board (CBSE, ICSE or State board)</li></ol><ul><li>Failed/Compartment Students from Other Boards (CBSE, ICSE, State Boards) This includes students who have failed in one or more subjects in their previous board exams.</li></ul><p>NIOS ODE allows them to reappear in those subjects—or even change the subject (to an easier elective or one of their choice).</p><p>📝 Important Even if you failed in just one subject (e.g., Physics), you must choose at least 3 subjects to appear for under ODE. These can be:</p><ul><li>Failed subjects</li><li>New subjects (check below that what are some subjects that you can choose in ODE.)</li><li>Previously passed subjects (to improve score or make up the required marks)</li></ul><p>🧾 ToC (Transfer of Credit)</p><ol><li><p>You can transfer up to two passed subjects&#39; marks from your original marksheet (e.g., CBSE) to NIOS. Final result A combined NIOS marksheet showing 5 subjects (2 from CBSE, 3 from ODE).</p></li><li><p>CBSE Passed Students (Dual/Part Admission) These are students who have already cleared Class 10 or 12 but want to add new subjects for:</p></li></ol><ul><li>College eligibility</li><li>Course requirements -Personal improvement 🧾 Key Points:</li><li>You can take 1-4 subjects under ODE.</li><li>ToC is not allowed in this category. You’ll receive a separate NIOS marksheet for these subjects (no combined result with your CBSE/State board marksheet)</li></ul><h1 id="tma-tutor-marked-assignment" tabindex="-1">TMA (Tutor Marked Assignment) <a class="header-anchor" href="#tma-tutor-marked-assignment" aria-label="Permalink to &quot;TMA (Tutor Marked Assignment)&quot;">​</a></h1><p>TMA is crucial for students as it carries <strong>20% weightage of your theory paper.</strong> <a href="https://drive.google.com/" target="_blank" rel="noreferrer">See subject-wise marks</a>. It is uploaded online on the <a href="https://sdmis.nios.ac.in/auth" target="_blank" rel="noreferrer">SDMIS website</a> only. TMA for vocational subjects <strong>does not exist</strong> (e.g., Data Entry-632). TMA is just Q&amp;A: they will ask you questions, and you are supposed to write the answers, take pictures, make a PDF file, and then upload them. TMA is only applicable for learners admitted under <strong>stream 1. No TMA for other streams.</strong></p><p><strong>Dates of TMA:</strong></p><ul><li><strong>Block-1 April:</strong> Starts in November, due on <strong>31st January</strong></li><li><strong>Block-2 October:</strong> Starts in June, due on <strong>31st July</strong></li></ul><h1 id="practical-examination-sa" tabindex="-1">Practical Examination/SA <a class="header-anchor" href="#practical-examination-sa" aria-label="Permalink to &quot;Practical Examination/SA&quot;">​</a></h1><p>Practical examinations are conducted at your study centre/AI (in most cases) 1 month before the public exams. For on-demand exams, <strong>please ask at the exam center for the date and time on the day of the theory paper.</strong> <a href="/wiki/pr.html">Detailed info on practicals</a></p><p><strong>Dates of Practical Exam:</strong></p><ul><li><strong>Block-1 April:</strong> March</li><li><strong>Block-2 October:</strong> September</li></ul><h1 id="pcp-personal-contact-programme" tabindex="-1">PCP (Personal Contact Programme) <a class="header-anchor" href="#pcp-personal-contact-programme" aria-label="Permalink to &quot;PCP (Personal Contact Programme)&quot;">​</a></h1><p>As we know, NIOS is an “open and distance learning system” wherein students don&#39;t have to go to school every day. PCP classes aren&#39;t meant for explaining the textbook; they are meant for doubt clearing. There are a total of <strong>35 classes</strong>:</p><ul><li>30 for doubt clearing (these do not carry any marks)</li><li>05 classes for <strong>only</strong> practical subjects. These carry <strong>50% weightage of practicals</strong>, i.e., if a subject has 20 max marks, 10 are for FA PCPs and 10 for the Practical exam, also known as SA/Sixth PCP/Final PCP.<br> PCP classes are for <strong>stream-1 learners only</strong>, and the marks for other streams transfer over to SA/Practical exams <a href="https://drive.google.com/file/d/19auYIHocmCcdMysj0dB0FeP_TciA5G_l/view?usp=drivesdk" target="_blank" rel="noreferrer">see this</a>.</li></ul><p>There are two types of PCPs:</p><ol><li><strong>PCP/Doubt Clearing:</strong> You ask the teacher doubts.</li><li><strong>FA Practical PCP:</strong> The teacher helps prepare for the practical file/record book and explains what to do in the practical examinations.</li></ol><p><strong>Dates of PCPs:</strong></p><p><strong>Block-1 April</strong></p><ul><li>PCP/Doubt Clearing: <strong>Nov-Jan</strong></li><li>FA PCP: <strong>Feb-Mar</strong></li></ul><p><strong>Block-2 October</strong></p><ul><li>PCP/Doubt Clearing: <strong>May-June</strong></li><li>FA PCP: <strong>Aug-Sept</strong></li></ul><p>Related links:</p><ol><li><a href="https://sdmis.nios.ac.in/search/pcp-hall-ticket" target="_blank" rel="noreferrer">PCP hall ticket</a></li><li><a href="https://sdmis.nios.ac.in/search/fa-hall-ticket" target="_blank" rel="noreferrer">FA PCP hall ticket</a></li></ol>',35)]))}const p=a(s,[["render",n]]);export{u as __pageData,p as default};
